INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload)
SELECT 'core-2026-09-v4','register-variation','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"register-variation","title":"Formal and informal grammar; British and American usage","level":"C1","order":67,"summary":"Recognise standard variation and choose a form that suits the audience rather than treating every difference as an error.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Contractions and formality","Standard varieties differ","Speech leaves more recoverable material unstated","Grammar supports a purpose"],"rules":[{"title":"Contractions and formality","explanation":"Contractions are normal in speech and much informal writing. Full forms can suit a formal notice or create emphasis. A contraction may be ambiguous until its complement is read: she’s can mean she is or she has; she’d can mean she had or she would.","pattern":"She’s **working** = she **is** working. / She’s **finished** = she **has** finished.","commonMistakes":["She’s finished can also mean she is finished in a different context. Read the full sentence rather than expanding mechanically."],"examples":["Expand “she’s” in “She’s preparing the visitor guide right now.” → **she is**","Expand “she’s” in “She’s restoring the old portrait right now.” → **she is**"],"skill":"form"},{"title":"Standard varieties differ","explanation":"British and American English share the central grammar system but differ in some preferences. British English often favours present perfect with just and already; American English also commonly uses past simple. Collective-noun agreement and some prepositions vary.","pattern":"I’ve just eaten. / I just ate.","commonMistakes":["A form common in another standard variety is not automatically an error. Practice questions specify a variety when the distinction matters."],"examples":["Expand “she’d” in “She’d prepare the visitor guide if she had time.” → **she would**","Expand “she’d” in “She’d restore the old portrait if she had time.” → **she would**"],"skill":"meaning"},{"title":"Speech leaves more recoverable material unstated","explanation":"Informal speech often uses ellipsis and short responses because the context is shared. Formal standalone writing usually needs clearer reference and fuller sentence structure. The choice depends on audience and purpose, not on one style being universally superior.","pattern":"Want a hand? → **Do you want** a hand?","commonMistakes":["A conversational fragment can be effective in dialogue while being unsuitable as an isolated formal report sentence."],"examples":["Rewrite “We won’t prepare the visitor guide today” using the full negative form. → **We will not prepare the visitor guide today.**","Rewrite “We won’t restore the old portrait today” using the full negative form. → **We will not restore the old portrait today.**"],"skill":"contrast"},{"title":"Grammar supports a purpose","explanation":"Polite modal questions, hedging and impersonal passives can soften a claim or request. Active clauses can make responsibility clearer. Use those tools deliberately: clarity is more important than adding complicated structures. Respect dialect differences while learning the standard forms appropriate to a particular setting.","pattern":"Could you check this? / We suggest that the team review it.","commonMistakes":["This course gives broad standard-English practice, not an exhaustive catalogue of dialect grammar or a certificate of fluency."],"examples":["Choose a standard polite modal request asking someone to prepare the visitor guide. → **Could you prepare the visitor guide, please?**","Choose a standard polite modal request asking someone to restore the old portrait. → **Could you restore the old portrait, please?**"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-varieties"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Recognise standard variation and choose a form that suits the audience rather than treating every difference as an error.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"Contractions and formality","explanation":"Contractions are normal in speech and much informal writing. Full forms can suit a formal notice or create emphasis. A contraction may be ambiguous until its complement is read: she’s can mean she is or she has; she’d can mean she had or she would.","pattern":"She’s **working** = she **is** working. / She’s **finished** = she **has** finished.","commonMistakes":["She’s finished can also mean she is finished in a different context. Read the full sentence rather than expanding mechanically."],"examples":["Expand “she’s” in “She’s preparing the visitor guide right now.” → **she is**","Expand “she’s” in “She’s restoring the old portrait right now.” → **she is**"],"skill":"form","id":"register-variation-foundation-1","domain":"usage","referenceIds":["bc-varieties"],"readingVersion":"core-2026-09-v3"},{"title":"Standard varieties differ","explanation":"British and American English share the central grammar system but differ in some preferences. British English often favours present perfect with just and already; American English also commonly uses past simple. Collective-noun agreement and some prepositions vary.","pattern":"I’ve just eaten. / I just ate.","commonMistakes":["A form common in another standard variety is not automatically an error. Practice questions specify a variety when the distinction matters."],"examples":["Expand “she’d” in “She’d prepare the visitor guide if she had time.” → **she would**","Expand “she’d” in “She’d restore the old portrait if she had time.” → **she would**"],"skill":"meaning","id":"register-variation-foundation-2","domain":"usage","referenceIds":["bc-varieties"],"readingVersion":"core-2026-09-v3"},{"title":"Speech leaves more recoverable material unstated","explanation":"Informal speech often uses ellipsis and short responses because the context is shared. Formal standalone writing usually needs clearer reference and fuller sentence structure. The choice depends on audience and purpose, not on one style being universally superior.","pattern":"Want a hand? → **Do you want** a hand?","commonMistakes":["A conversational fragment can be effective in dialogue while being unsuitable as an isolated formal report sentence."],"examples":["Rewrite “We won’t prepare the visitor guide today” using the full negative form. → **We will not prepare the visitor guide today.**","Rewrite “We won’t restore the old portrait today” using the full negative form. → **We will not restore the old portrait today.**"],"skill":"contrast","id":"register-variation-foundation-3","domain":"usage","referenceIds":["bc-varieties"],"readingVersion":"core-2026-09-v3"},{"title":"Grammar supports a purpose","explanation":"Polite modal questions, hedging and impersonal passives can soften a claim or request. Active clauses can make responsibility clearer. Use those tools deliberately: clarity is more important than adding complicated structures. Respect dialect differences while learning the standard forms appropriate to a particular setting.","pattern":"Could you check this? / We suggest that the team review it.","commonMistakes":["This course gives broad standard-English practice, not an exhaustive catalogue of dialect grammar or a certificate of fluency."],"examples":["Choose a standard polite modal request asking someone to prepare the visitor guide. → **Could you prepare the visitor guide, please?**","Choose a standard polite modal request asking someone to restore the old portrait. → **Could you restore the old portrait, please?**"],"skill":"application","id":"register-variation-foundation-4","domain":"usage","referenceIds":["bc-varieties"],"readingVersion":"core-2026-09-v3"},{"domain":"negation","id":"double-negation-and-concord","title":"Double negation, negative concord and litotes","explanation":"Two negatives can cancel or soften one another in standard English, as in not impossible. In some dialects, multiple negative forms instead express a single negative meaning; this systematic pattern is called negative concord. Recognising dialect grammar is different from choosing the standard form expected in a formal document.","pattern":"**not impossible** / **not without difficulty**","examples":["The result was **not unexpected**.","Standard formal wording: **I didn’t see anything**."],"commonMistakes":["Not bad is often praise rather than a literal claim of neutrality. Context determines the pragmatic force of a softened negative."],"referenceIds":["cambridge-negation","cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"usage","id":"hedging-and-stance","title":"Hedging: expressing uncertainty and softening a claim","explanation":"Hedging adjusts the strength or directness of a statement through modals, stance verbs, adverbs and approximating expressions. It can reflect genuine uncertainty or interpersonal care. Choose wording proportional to the evidence rather than making every sentence vague. Stronger expressions can signal greater commitment when it is justified.","pattern":"It **seems that**… / This **may suggest**…","examples":["The change **appears to have helped**.","I’m **not entirely sure** that this is the best option."],"commonMistakes":["Might and seems do not make an unsupported claim reliable. Hedging changes the speaker’s commitment; it does not supply evidence."],"referenceIds":["cambridge-hedges","cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"usage","id":"spoken-headers-tails","title":"Headers and tails in spoken English","explanation":"Conversation can introduce a topic before the main clause and then refer to it with a pronoun; this is a header. A tail names or clarifies a referent after the clause. These patterns help listeners process a message in real time. They are especially associated with speech and informal contexts rather than neutral edited exposition.","pattern":"**That new café**, it’s always busy.","examples":["She’s very patient, **your sister**.","**The train we caught**, it stopped at every station."],"commonMistakes":["A spoken header is a licensed discourse pattern, not a model for every formal sentence. In formal writing, The new café is always busy is often more suitable."],"referenceIds":["cambridge-headers-tails","cambridge-spoken"],"readingVersion":"core-2026-09-v4"},{"domain":"usage","id":"discourse-markers-response-tokens","title":"Discourse markers, response tokens and interjections","explanation":"Words such as well, so, anyway and right help organise turns, transitions and responses. Oh, ah and similar interjections can mark a reaction or a change of understanding. Their conversational job may be separate from the propositional content. Some linking expressions suit formal writing; others mainly suit speech.","pattern":"**Well**, I’m not sure. / **Anyway**, let’s continue.","examples":["**Oh**, I thought the meeting was tomorrow.","**Right**, shall we begin?"],"commonMistakes":["So can link a result, introduce a new topic or request continuation. Identify its function in the actual exchange rather than assigning one meaning to every occurrence."],"referenceIds":["cambridge-spoken","cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"usage","id":"politeness-distance-indirectness","title":"Politeness, grammatical distance and indirect requests","explanation":"Past forms and modal constructions can create interpersonal distance without referring to past time. Indirect questions and conditional wording can soften requests, while concise imperatives can be appropriate in instructions. Politeness depends on relationship, situation and tone as well as grammatical form. More words do not automatically make a request more considerate.","pattern":"I **was wondering** if you could help.","examples":["**Would you mind opening** the window?","**Could I ask you to wait** a moment?"],"commonMistakes":["Would you mind…? conventionally takes an -ing clause; a reply such as Not at all normally accepts the request. Consider the meaning before interpreting yes or no."],"referenceIds":["cambridge-spoken","cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"usage","id":"regional-standard-variation","title":"British, American and other standard varieties","explanation":"Standard English is shared across communities but includes regional preferences in tense, agreement, prepositions and certain constructions. British English often uses present perfect with just or already where American English also uses past simple. Collective agreement and institutional articles show further variation. Label the intended variety when a question depends on it.","pattern":"BrE **in hospital** / AmE **in the hospital**","examples":["BrE often: **Have you eaten yet?** / AmE also: **Did you eat yet?**","BrE **at the weekend** / AmE **on the weekend**."],"commonMistakes":["These are tendencies, not a rule that every British or American speaker makes the same choice. Regional varieties beyond these two also have established standard conventions."],"referenceIds":["cambridge-spoken","cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"usage","id":"formal-informal-and-genres","title":"Formal writing, informal language and genre","explanation":"Grammar choices respond to audience and purpose. Academic and official writing often make reference and logical relationships explicit; conversation can depend on shared context. Headlines, instructions, notes and literary narration have their own conventional reductions and patterns. A form appropriate in one genre may be distracting in another without being universally wrong.","pattern":"**No entry** in a sign / **Visitors must not enter** in a rule","examples":["A headline may say **Mayor opens new library**.","An instruction may begin **Add the flour**."],"commonMistakes":["Do not equate every informal construction with an error or every passive with good formal style. Choose the structure that expresses the intended relationship clearly."],"referenceIds":["cambridge-spoken","cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"usage","id":"grammar-conventions-and-change","title":"Rules, preferences, variation and language change","explanation":"Some constraints define a standard construction; others are strong preferences or editorial conventions. English changes and permits more variation than a short rule often suggests. Dictionaries and reference grammars help resolve lexical and regional questions. A useful learner grammar explains both the stable pattern and the contexts in which alternatives occur.","pattern":"a **construction rule** / a **style preference**","examples":["**Who are you talking to?** is standard despite its final preposition.","**To clearly explain** can be appropriate; split infinitives are not universally ungrammatical."],"commonMistakes":["A grammar map describes systems and productive patterns. It cannot list every possible sentence, every lexical idiom or all historical and regional constructions as a finite exercise bank."],"referenceIds":["cambridge-spoken","cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["She’s **working** = she **is** working. / She’s **finished** = she **has** finished.","I’ve just eaten. / I just ate.","Want a hand? → **Do you want** a hand?","Could you check this? / We suggest that the team review it."],"readingVersion":"core-2026-09-v4"},"stage":"6 · Advanced control","prerequisites":["noun-modifiers"],"readingReferenceIds":["bc-varieties","cambridge-negation","cambridge-comprehensive-scope","cambridge-hedges","cambridge-headers-tails","cambridge-spoken"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='register-variation'
